SELECT id, username, nickname, email, phone, avatar_url, gender, status, last_login_at, created_at, updated_at 
FROM users 
WHERE id = #{id}

SELECT id, username, nickname, email, phone, avatar_url, gender, status, last_login_at, created_at, updated_at
FROM users


        AND (username LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%'))


        AND gender = #{gender}


        AND status = #{status}


ORDER BY id DESC
